<span class="line">                    cell<span class="token punctuation">.</span>lon_min <span class="token operator">&lt;=</span> lon <span class="token operator">&lt;=</span> cell<span class="token punctuation">.</span>lon_max<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
